// ==========================================
// DCA (Dollar Cost Averaging) CONFIGURATION
// ==========================================
// Edit these settings to match your strategy

const CONFIG = {
  // Trading pair
  symbol: 'BTCUSDT',

  // Amount in USDT per buy order
  orderAmountUSDT: 50,

  // Only buy if price dropped more than X% from last buy
  dipThreshold: 2.0,

  // Take profit percentage
  takeProfitPct: 5.0,

  // Stop loss percentage (0 = disabled)
  stopLossPct: 10.0,

  // Max total investment in USDT (safety limit)
  maxTotalInvestment: 1000,

  // Use testnet (SET TO true FOR TESTING!)
  useTestnet: true,

  // Order type: 'Market' or 'Limit'
  orderType: 'Market'
};

return [{ json: CONFIG }];

const config = $input.first().json;
const baseUrl = config.useTestnet 
  ? 'https://api-testnet.bybit.com' 
  : 'https://api.bybit.com';

// Get current price
const tickerResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/v5/market/tickers?category=spot&symbol=${config.symbol}`,
});

const currentPrice = parseFloat(tickerResponse.result.list[0].lastPrice);

// Get wallet balance
const timestamp = Date.now().toString();
const apiKey = $env.BYBIT_API_KEY;
const apiSecret = $env.BYBIT_API_SECRET;

// HMAC signature for Bybit V5 API
const crypto = require('crypto');
const recvWindow = '5000';
const queryString = `accountType=UNIFIED`;
const preSign = timestamp + apiKey + recvWindow + queryString;
const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');

const balanceResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/v5/account/wallet-balance?accountType=UNIFIED`,
  headers: {
    'X-BAPI-API-KEY': apiKey,
    'X-BAPI-SIGN': signature,
    'X-BAPI-TIMESTAMP': timestamp,
    'X-BAPI-RECV-WINDOW': recvWindow,
    'Content-Type': 'application/json'
  }
});

let usdtBalance = 0;
try {
  const coins = balanceResponse.result.list[0].coin;
  const usdt = coins.find(c => c.coin === 'USDT');
  usdtBalance = usdt ? parseFloat(usdt.walletBalance) : 0;
} catch(e) {
  usdtBalance = 0;
}

// Get stored state
const store = $getWorkflowStaticData('global');
if (!store.lastBuyPrice) store.lastBuyPrice = 0;
if (!store.totalInvested) store.totalInvested = 0;
if (!store.avgBuyPrice) store.avgBuyPrice = 0;
if (!store.totalQuantity) store.totalQuantity = 0;

return [{
  json: {
    ...config,
    currentPrice,
    usdtBalance,
    lastBuyPrice: store.lastBuyPrice,
    totalInvested: store.totalInvested,
    avgBuyPrice: store.avgBuyPrice,
    totalQuantity: store.totalQuantity,
    baseUrl
  }
}];

const data = $input.first().json;
const store = $getWorkflowStaticData('global');

let action = 'HOLD';
let reason = '';

const { currentPrice, lastBuyPrice, totalInvested, avgBuyPrice, totalQuantity,
        orderAmountUSDT, dipThreshold, takeProfitPct, stopLossPct, 
        maxTotalInvestment, usdtBalance } = data;

// Check take profit
if (avgBuyPrice > 0 && totalQuantity > 0) {
  const profitPct = ((currentPrice - avgBuyPrice) / avgBuyPrice) * 100;

  if (profitPct >= takeProfitPct) {
    action = 'SELL';
    reason = `Take profit: ${profitPct.toFixed(2)}% (target: ${takeProfitPct}%)`;
  }

  if (stopLossPct > 0 && profitPct <= -stopLossPct) {
    action = 'SELL';
    reason = `Stop loss: ${profitPct.toFixed(2)}% (limit: -${stopLossPct}%)`;
  }
}

// Check DCA buy condition
if (action === 'HOLD') {
  const dipFromLast = lastBuyPrice > 0 
    ? ((lastBuyPrice - currentPrice) / lastBuyPrice) * 100 
    : dipThreshold + 1; // First buy always triggers

  if (dipFromLast >= dipThreshold) {
    if (totalInvested + orderAmountUSDT <= maxTotalInvestment) {
      if (usdtBalance >= orderAmountUSDT) {
        action = 'BUY';
        reason = `DCA buy: price dropped ${dipFromLast.toFixed(2)}% from last buy`;
      } else {
        reason = `Insufficient balance: ${usdtBalance.toFixed(2)} USDT`;
      }
    } else {
      reason = `Max investment reached: ${totalInvested.toFixed(2)}/${maxTotalInvestment} USDT`;
    }
  } else {
    reason = `Price drop ${dipFromLast.toFixed(2)}% < threshold ${dipThreshold}%`;
  }
}

return [{
  json: {
    ...data,
    action,
    reason
  }
}];

const data = $input.first().json;
const crypto = require('crypto');

const apiKey = $env.BYBIT_API_KEY;
const apiSecret = $env.BYBIT_API_SECRET;
const timestamp = Date.now().toString();
const recvWindow = '5000';

// Calculate quantity
const qty = (data.orderAmountUSDT / data.currentPrice).toFixed(6);

const orderPayload = {
  category: 'spot',
  symbol: data.symbol,
  side: 'Buy',
  orderType: data.orderType,
  qty: data.orderType === 'Market' ? data.orderAmountUSDT.toString() : qty,
  marketUnit: data.orderType === 'Market' ? 'quoteCoin' : undefined
};

const bodyStr = JSON.stringify(orderPayload);
const preSign = timestamp + apiKey + recvWindow + bodyStr;
const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: `${data.baseUrl}/v5/order/create`,
  headers: {
    'X-BAPI-API-KEY': apiKey,
    'X-BAPI-SIGN': signature,
    'X-BAPI-TIMESTAMP': timestamp,
    'X-BAPI-RECV-WINDOW': recvWindow,
    'Content-Type': 'application/json'
  },
  body: orderPayload
});

// Update stored state
const store = $getWorkflowStaticData('global');
const buyQty = parseFloat(qty);
const buyAmount = data.orderAmountUSDT;

store.totalQuantity = (store.totalQuantity || 0) + buyQty;
store.totalInvested = (store.totalInvested || 0) + buyAmount;
store.avgBuyPrice = store.totalInvested / store.totalQuantity;
store.lastBuyPrice = data.currentPrice;

return [{
  json: {
    action: 'BUY',
    symbol: data.symbol,
    price: data.currentPrice,
    qty: qty,
    amountUSDT: buyAmount,
    orderId: response.result?.orderId || 'N/A',
    retCode: response.retCode,
    retMsg: response.retMsg,
    totalInvested: store.totalInvested,
    avgPrice: store.avgBuyPrice,
    reason: data.reason
  }
}];

const data = $input.first().json;
const crypto = require('crypto');

const apiKey = $env.BYBIT_API_KEY;
const apiSecret = $env.BYBIT_API_SECRET;
const timestamp = Date.now().toString();
const recvWindow = '5000';

const store = $getWorkflowStaticData('global');
const sellQty = (store.totalQuantity || 0).toFixed(6);

const orderPayload = {
  category: 'spot',
  symbol: data.symbol,
  side: 'Sell',
  orderType: 'Market',
  qty: sellQty
};

const bodyStr = JSON.stringify(orderPayload);
const preSign = timestamp + apiKey + recvWindow + bodyStr;
const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: `${data.baseUrl}/v5/order/create`,
  headers: {
    'X-BAPI-API-KEY': apiKey,
    'X-BAPI-SIGN': signature,
    'X-BAPI-TIMESTAMP': timestamp,
    'X-BAPI-RECV-WINDOW': recvWindow,
    'Content-Type': 'application/json'
  },
  body: orderPayload
});

// Calculate P&L
const pnl = (data.currentPrice * parseFloat(sellQty)) - (store.totalInvested || 0);
const pnlPct = store.avgBuyPrice > 0 
  ? ((data.currentPrice - store.avgBuyPrice) / store.avgBuyPrice * 100).toFixed(2)
  : 0;

// Reset state
store.totalQuantity = 0;
store.totalInvested = 0;
store.avgBuyPrice = 0;
store.lastBuyPrice = 0;

return [{
  json: {
    action: 'SELL',
    symbol: data.symbol,
    price: data.currentPrice,
    qty: sellQty,
    orderId: response.result?.orderId || 'N/A',
    retCode: response.retCode,
    retMsg: response.retMsg,
    pnl: pnl.toFixed(2),
    pnlPct: pnlPct,
    reason: data.reason
  }
}];

const data = $input.first().json;
return [{
  json: {
    action: 'HOLD',
    symbol: data.symbol,
    price: data.currentPrice,
    reason: data.reason
  }
}];

const data = $input.first().json;

let emoji = '📊';
if (data.action === 'BUY') emoji = '🟢';
if (data.action === 'SELL') emoji = data.pnl >= 0 ? '🟢💰' : '🔴';
if (data.action === 'HOLD') emoji = '⏸';

let message = `${emoji} <b>Bybit DCA Bot</b>\n\n`;
message += `<b>Действие:</b> ${data.action}\n`;
message += `<b>Пара:</b> ${data.symbol}\n`;
message += `<b>Цена:</b> <code>$${data.price}</code>\n`;

if (data.action === 'BUY') {
  message += `<b>Куплено:</b> ${data.qty} (${data.amountUSDT} USDT)\n`;
  message += `<b>Order ID:</b> <code>${data.orderId}</code>\n`;
  message += `<b>Ср. цена:</b> $${data.avgPrice?.toFixed(2) || 'N/A'}\n`;
  message += `<b>Всего вложено:</b> $${data.totalInvested?.toFixed(2) || 'N/A'}\n`;
}

if (data.action === 'SELL') {
  message += `<b>Продано:</b> ${data.qty}\n`;
  message += `<b>Order ID:</b> <code>${data.orderId}</code>\n`;
  message += `<b>P&L:</b> $${data.pnl} (${data.pnlPct}%)\n`;
}

message += `<b>Причина:</b> ${data.reason}\n`;
message += `\n⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

if (data.retCode !== undefined && data.retCode !== 0) {
  message += `\n\n⚠️ <b>Ошибка API:</b> ${data.retMsg}`;
}

return [{ json: { message } }];
